// factory.spec.js — generic checks every WebFactory tool must pass. Generated by the factory; do not edit.
// Tool-specific checks (the core action on a bundled fixture) live in smoke.spec.js.
const { test, expect } = require('@playwright/test');

const ALLOWED_HOSTS = ["claude.com", "gc.zgo.at", "github.com", "img.shields.io", "ko-fi.com", "opensource.org", "schema.org", "turhe123.github.io", "turhe123.goatcounter.com", "www.goatcounter.com", "www.sitemaps.org", "www.w3.org"]; // third-party hosts the page may talk to (page-view counter, links)
const REPO_URL = 'https://github.com/turhe123/unzip-files-local';
const DONATION_URL = 'https://ko-fi.com/leodavidai';

// Same-origin = the server under test (local http.server, or the live GitHub Pages URL via BASE_URL).
const SITE_HOST = new URL(process.env.BASE_URL || 'http://127.0.0.1/').hostname;
const isSite = (h) => h === SITE_HOST || h === '127.0.0.1' || h === 'localhost';

function watch(page) {
  const state = { consoleErrors: [], pageErrors: [], failed: [], external: [] };
  page.on('console', (m) => { if (m.type() === 'error') state.consoleErrors.push(m.text()); });
  page.on('pageerror', (e) => state.pageErrors.push(String(e)));
  page.on('requestfailed', (r) => { const u = new URL(r.url()); if (isSite(u.hostname)) state.failed.push(r.url()); });
  return state;
}

async function blockExternal(page, state) {
  await page.route('**/*', (route) => {
    const u = new URL(route.request().url());
    if (isSite(u.hostname)) return route.continue();
    state.external.push(u.hostname);
    if (ALLOWED_HOSTS.includes(u.hostname)) return route.fulfill({ status: 200, contentType: 'application/javascript', body: '' });
    return route.abort();
  });
}

test.describe('factory checks', () => {
  test('loads with a search-ready title, description and structured data', async ({ page }) => {
    const state = watch(page);
    await blockExternal(page, state);
    const res = await page.goto('./');
    expect(res.ok()).toBeTruthy();
    const title = await page.title();
    expect(title.length).toBeGreaterThan(10);
    expect(title.length).toBeLessThanOrEqual(75);
    expect(title).not.toContain('$');
    const desc = await page.locator('meta[name="description"]').getAttribute('content');
    expect(desc.length).toBeGreaterThanOrEqual(50);
    expect(desc.length).toBeLessThanOrEqual(175);
    expect(desc).not.toContain('$');
    const ld = await page.locator('script[type="application/ld+json"]').first().textContent();
    const data = JSON.parse(ld);
    expect(data['@type']).toBe('SoftwareApplication');
    expect(data.name.length).toBeGreaterThan(2);
    await expect(page.locator('html')).toHaveAttribute('lang', /.+/);
    await expect(page.locator('link[rel="manifest"]')).toHaveCount(1);
    await expect(page.locator('h1')).toBeVisible();
    await expect(page.locator('#tool')).toBeVisible();
  });

  test('no console errors, no failed requests, no third-party traffic', async ({ page }) => {
    const state = watch(page);
    await blockExternal(page, state);
    await page.goto('./');
    await page.waitForLoadState('networkidle');
    await page.waitForTimeout(500);
    expect(state.pageErrors, 'uncaught exceptions').toEqual([]);
    expect(state.consoleErrors, 'console errors').toEqual([]);
    expect(state.failed, 'failed same-origin requests').toEqual([]);
    const disallowed = state.external.filter((h) => !ALLOWED_HOSTS.includes(h));
    expect(disallowed, 'requests to non-allowlisted hosts').toEqual([]);
  });

  test('footer has the source link, Ko-fi link and AI disclosure', async ({ page }) => {
    const state = watch(page);
    await blockExternal(page, state);
    await page.goto('./');
    const footer = page.locator('footer');
    await expect(footer.locator(`a[href^="${REPO_URL}"]`).first()).toBeVisible();
    await expect(footer.locator(`a[href^="${DONATION_URL}"]`).first()).toBeVisible();
    await expect(footer).toContainText(/Built with AI/i);
    await expect(page.locator('#faq details')).not.toHaveCount(0);
  });

  test('fits a 390px phone without horizontal scroll', async ({ page }) => {
    const state = watch(page);
    await blockExternal(page, state);
    await page.setViewportSize({ width: 390, height: 844 });
    await page.goto('./');
    await page.waitForLoadState('networkidle');
    const widths = await page.evaluate(() => ({ doc: document.documentElement.scrollWidth, win: window.innerWidth }));
    expect(widths.doc, 'page is wider than the viewport').toBeLessThanOrEqual(widths.win + 1);
    await expect(page.locator('#tool')).toBeVisible();
    const box = await page.locator('#tool').boundingBox();
    expect(box.y, 'tool must be near the top on phones').toBeLessThan(844 * 1.6);
  });

  test('has a real dark theme and a light theme', async ({ page }) => {
    const state = watch(page);
    await blockExternal(page, state);
    await page.emulateMedia({ colorScheme: 'light' });
    await page.goto('./');
    const light = await page.evaluate(() => getComputedStyle(document.body).backgroundColor);
    await page.emulateMedia({ colorScheme: 'dark' });
    await page.waitForTimeout(100);
    const dark = await page.evaluate(() => getComputedStyle(document.body).backgroundColor);
    expect(dark).not.toBe(light);
    expect(state.pageErrors).toEqual([]);
  });

  test('basic accessibility: alt text, labels, named buttons, visible focus', async ({ page }) => {
    const state = watch(page);
    await blockExternal(page, state);
    await page.goto('./');
    const problems = await page.evaluate(() => {
      const out = [];
      document.querySelectorAll('img').forEach((img) => { if (!img.hasAttribute('alt')) out.push(`img without alt: ${img.getAttribute('src')}`); });
      document.querySelectorAll('button').forEach((b) => {
        const name = (b.textContent || '').trim() || b.getAttribute('aria-label') || b.getAttribute('title');
        if (!name) out.push(`button without a name: ${b.outerHTML.slice(0, 80)}`);
      });
      document.querySelectorAll('input:not([type=hidden]), select, textarea').forEach((el) => {
        const id = el.id;
        const labelled = el.getAttribute('aria-label') || el.getAttribute('aria-labelledby') || (id && document.querySelector(`label[for="${id}"]`)) || el.closest('label');
        if (!labelled) out.push(`form control without a label: ${el.outerHTML.slice(0, 80)}`);
      });
      return out;
    });
    expect(problems).toEqual([]);
    await page.keyboard.press('Tab');
    const focused = await page.evaluate(() => document.activeElement && document.activeElement.tagName);
    expect(focused).toBeTruthy();
  });

  test('registers a service worker and works offline after the first visit', async ({ page, context }) => {
    const state = watch(page);
    await blockExternal(page, state);
    await page.goto('./');
    await page.evaluate(() => navigator.serviceWorker.ready);
    await expect.poll(async () => page.evaluate(async () => {
      const keys = await caches.keys();
      if (!keys.length) return false;
      const c = await caches.open(keys[0]);
      return Boolean(await c.match('./index.html') || await c.match('index.html'));
    }), { timeout: 20_000 }).toBeTruthy();
    await context.setOffline(true);
    await page.reload();
    await expect(page.locator('h1')).toBeVisible();
    await expect(page.locator('#tool')).toBeVisible();
    const cssOk = await page.evaluate(() => getComputedStyle(document.querySelector('.tool-card')).borderTopLeftRadius !== '0px');
    expect(cssOk, 'stylesheet did not load offline').toBeTruthy();
    await context.setOffline(false);
  });
});
